#!/usr/bin/env node
"use strict";

/*
 * Logic test for long-hanoi/long-hanoi-core.js.
 *
 *   1. solution() is longhanoicanvas.Solution(N, Src, Aux, Dst), transcribed
 *      here a second time from the bytecode and compared over every disk
 *      count and all six peg orderings; for N = 3 it is exactly the move list
 *      printed on the cut-the-knot page.
 *   2. The page's claims: 3^N - 1 moves, T_N = 3T_(N-1) + 2, and "the states
 *      generated by the algorithm are all distinct" - checked by playing it
 *      out to N = 9, where it turns out to visit all 3^N positions, one each.
 *      That it is the longest route possible is checked independently, by an
 *      exhaustive longest-path search to N = 4.
 *   3. rank() and unrank() against every position, and suggest() followed from
 *      every position, to N = 8.
 *   4. The rules: the no-repeat rule, dead ends, the win test, and the two
 *      leftovers the port drops - the applet's Help(), transcribed from the
 *      bytecode, plays the shortest solution, and its Approve() tells a
 *      perfect long solve to use fewer moves.
 */

import { loadCore, check, equal, done } from "./lib/load-core.mjs";

const H = loadCore("long-hanoi/long-hanoi-core.js", "LongHanoiCore");

/* ------------------------------------------------------- 1. the recursion */

// Solution(int, int, int, int), straight off the bytecode: recurse, push
// Point(src, aux), recurse with (dst, aux, src), push Point(aux, dst), recurse.
function appletSolution(n, src, aux, dst, moves = []) {
  if (n === 0) return moves;
  appletSolution(n - 1, src, aux, dst, moves);
  moves.push([src, aux]);
  appletSolution(n - 1, dst, aux, src, moves);
  moves.push([aux, dst]);
  appletSolution(n - 1, src, aux, dst, moves);
  return moves;
}

const ORDERS = [[0, 1, 2], [0, 2, 1], [1, 0, 2], [1, 2, 0], [2, 0, 1], [2, 1, 0]];
let differ = 0;
for (let n = 0; n <= H.MAX_DISKS; n++) {
  for (const [s, a, d] of ORDERS) {
    if (JSON.stringify(H.solution(n, s, a, d)) !== JSON.stringify(appletSolution(n, s, a, d))) differ++;
  }
}
check("solution() = the applet's Solution() for every size and peg order", differ === 0, `${differ} differ`);

const NAMES = ["Src", "Aux", "Dst"];
const PAGE_3 = [
  "Src-Aux", "Aux-Dst", "Src-Aux", "Dst-Aux", "Aux-Src", "Aux-Dst", "Src-Aux",
  "Aux-Dst", "Src-Aux", "Dst-Aux", "Aux-Src", "Dst-Aux", "Src-Aux", "Aux-Dst",
  "Aux-Src", "Dst-Aux", "Aux-Src", "Aux-Dst", "Src-Aux", "Aux-Dst", "Src-Aux",
  "Dst-Aux", "Aux-Src", "Aux-Dst", "Src-Aux", "Aux-Dst",
];
equal("Solution(3) is the page's list", H.solution(3).map(([a, b]) => NAMES[a] + "-" + NAMES[b]), PAGE_3);

/* ------------------------------------------------------ 2. the page's claims */


// T_N = 3T_(N-1) + 2 with T_0 = 0, so T_N = 3^N - 1.
let recurrence = true;
for (let n = 1; n <= H.MAX_DISKS; n++) {
  if (H.longest(n) !== 3 * H.longest(n - 1) + 2) recurrence = false;
}
check("T_N = 3T_(N-1) + 2 gives 3^N - 1", recurrence);

for (let n = 1; n <= 9; n++) {
  const s = H.start(n);
  const moves = H.solution(n);
  equal(`${n} disks: the long solution takes 3^n - 1 moves`, moves.length, 3 ** n - 1);

  // move() refuses an illegal move and a repeat, so playing the whole list
  // through it proves both at once: legal throughout and never a repeat.
  const states = [H.key(s)];
  const played = moves.every(([a, b]) => {
    const ok = H.move(s, a, b);
    states.push(H.key(s));
    return ok;
  });
  check(`${n} disks: the long solution is legal and never repeats a position`, played);
  check(`${n} disks: it ends with every disk on the right peg`, H.won(s));
  equal(`${n} disks: the states it generates are all distinct`, new Set(states).size, 3 ** n);
  equal(`${n} disks: so it visits all 3^n positions`, states.length, 3 ** n);

  // Not on the page, but the reason the route can be that long: the big disk
  // has to sit on the middle peg for a third of it, and in fact no disk ever
  // goes straight from the left peg to the right one.
  check(`${n} disks: every move touches the middle peg`, moves.every(([a, b]) => a === H.AUX || b === H.AUX));
}

// "you can at most use 3^n - 1 different moves". The ceiling is a count: a
// route that never repeats visits each position at most once, so breadth-first
// search over the position graph settles how many there are. That the ceiling
// is reached is settled above, by playing the long solution out. For the
// smallest boards an exhaustive longest-path search checks both at once.
function neighbours(pegOf) {
  const out = [];
  const tops = [Infinity, Infinity, Infinity];
  pegOf.forEach((p, i) => { if (i + 1 < tops[p]) tops[p] = i + 1; });
  for (let a = 0; a < 3; a++) {
    if (tops[a] === Infinity) continue;
    for (let b = 0; b < 3; b++) {
      if (a !== b && tops[a] < tops[b]) {
        const next = pegOf.slice();
        next[tops[a] - 1] = b;
        out.push(next.join(""));
      }
    }
  }
  return out;
}
function longestPath(n) {
  const goal = "2".repeat(n);
  const seen = new Set();
  let best = 0;
  (function walk(at, depth) {
    if (at === goal) { if (depth > best) best = depth; return; }
    seen.add(at);
    for (const nb of neighbours(at.split("").map(Number))) {
      if (!seen.has(nb)) walk(nb, depth + 1);
    }
    seen.delete(at);
  })("0".repeat(n), 0);
  return best;
}
for (let n = 1; n <= 8; n++) {
  const all = new Set(["0".repeat(n)]);
  const queue = ["0".repeat(n)];
  for (let i = 0; i < queue.length; i++) {
    for (const nb of neighbours(queue[i].split("").map(Number))) {
      if (!all.has(nb)) { all.add(nb); queue.push(nb); }
    }
  }
  equal(`${n} disks: there are 3^n positions in all`, all.size, 3 ** n);
  equal(`${n} disks: so no route can be longer than 3^n - 1`, H.longest(n), all.size - 1);
}
// An exhaustive search for the longest route, where it is affordable: the
// 4-disk search takes a minute and a half, so the gate stops at three.
for (let n = 1; n <= 3; n++) {
  equal(`${n} disks: the longest no-repeat route really is 3^n - 1`, longestPath(n), 3 ** n - 1);
}

/* ------------------------------------------- 3. the position numbering */

function fromKey(key) {
  const pegOf = key.split("").map(Number);
  const s = H.start(pegOf.length);
  s.pegs = [[], [], []];
  for (let d = pegOf.length; d >= 1; d--) s.pegs[pegOf[d - 1]].push(d);
  s.seen = new Set([key]);
  return s;
}

for (let n = 1; n <= 8; n++) {
  const last = 3 ** n - 1;
  const ranks = new Set();
  let roundTrip = true;
  for (let r = 0; r <= last; r++) {
    const pegOf = H.unrank(n, r);
    ranks.add(pegOf.join(""));
    if (H.rank(fromKey(pegOf.join(""))) !== r) roundTrip = false;
  }
  check(`${n} disks: unrank() numbers all 3^n positions, rank() undoes it`, roundTrip && ranks.size === 3 ** n);
  equal(`${n} disks: the start is step 0`, H.rank(H.start(n)), 0);
  equal(`${n} disks: the finish is step 3^n - 1`, H.rank(fromKey("2".repeat(n))), last);

  // From anywhere, following "Suggest move" walks the rest of the route.
  // Playing out all 3^n of them is quadratic, so it stops at six disks.
  if (n > 6) continue;
  let strays = 0;
  for (const key of ranks) {
    const s = fromKey(key);
    const want = last - H.rank(s);
    let steps = 0;
    while (!H.won(s)) {
      const m = H.suggest(s);
      if (!m || !H.move(s, m[0], m[1])) break;
      steps++;
    }
    if (!H.won(s) || steps !== want) strays++;
  }
  check(`${n} disks: suggest() finishes the route from every position`, strays === 0, `${strays} stray`);
}

/* ---------------------------------------------- 4. rules, dead ends, leftovers */

{
  const s = H.start(3);
  check("cannot move from an empty peg", !H.legal(s, 1, 2));
  check("cannot drop on the same peg", !H.legal(s, 0, 0));
  check("a disk goes on an empty peg", H.move(s, 0, 1));
  check("no disk on a smaller one", !H.legal(s, 0, 1));
  check("moving straight back is legal but repeats", H.legal(s, 1, 0) && H.repeats(s, 1, 0));
  check("so move() refuses it", !H.move(s, 1, 0));
  equal("and the move count stands", s.moves, 1);
  check("not home yet", !H.won(s) && !H.stuck(s));
}

{
  // One disk: the only two moves are the long route, and both are forced.
  const s = H.start(1);
  check("one disk: left to middle", H.move(s, 0, 1));
  check("one disk: middle to right", H.move(s, 1, 2));
  check("one disk: home in 2 = 3^1 - 1", H.won(s) && s.moves === 2);
  equal("one disk: the perfect verdict", H.verdict(s), "Congratulations! All 2 moves \u2014 the longest route there is.");
}

{
  // The shortest route is still a win, just not the longest one.
  const s = H.start(2);
  [[0, 1], [0, 2], [1, 2]].forEach(([a, b]) => H.move(s, a, b));
  check("two disks: home in 3 moves", H.won(s) && s.moves === 3);
  equal("two disks: the verdict names the longest", H.verdict(s), "Congratulations! 3 moves. The longest route takes 8.");
}

{
  // The shortest dead end there is with two disks, found by searching every
  // no-repeat route: four moves, and the tower is stranded on the middle peg.
  const s = H.start(2);
  const path = [[0, 2], [0, 1], [2, 0], [0, 1]];
  check("two disks: the dead-end path is playable", path.every(([a, b]) => H.move(s, a, b)));
  equal("two disks: it ends with the whole tower on the middle peg", H.key(s), "11");
  check("two disks: every move from there repeats a position", H.stuck(s));
  check("two disks: and it is not a win", !H.won(s));
  equal("two disks: suggest() has nothing to offer", H.suggest(s), null);
}

{
  // Dead ends are not a two-disk curiosity: they exist for 3 and 4 disks too.
  for (let n = 3; n <= 4; n++) {
    let found = false;
    (function walk(s) {
      if (found || H.won(s)) return;
      if (H.stuck(s)) { found = true; return; }
      for (let a = 0; a < 3 && !found; a++) {
        for (let b = 0; b < 3 && !found; b++) {
          if (!H.legal(s, a, b) || H.repeats(s, a, b)) continue;
          const copy = fromKey(H.key(s));
          copy.seen = new Set(s.seen);
          copy.moves = s.moves;
          H.move(copy, a, b);
          walk(copy);
        }
      }
    })(H.start(n));
    check(`${n} disks: a dead end exists`, found);
  }
}

// Help(), from the bytecode of the plain hanoi applet this one was copied
// from: it walks down from the biggest disk towards a target peg. It is the
// shortest solution's next move, which is why the port does not use it.
function appletHelp(s) {
  const pos = H.key(s).split("").map(Number);
  let i = 2;
  let found = -1;
  for (let k = s.n; k > 0; k--) {
    const stack = s.pegs[pos[k - 1]];
    const peek = stack[stack.length - 1];
    if (i === pos[k - 1]) continue;
    if (peek === k) {
      if (s.pegs[i].length === 0) { found = k; break; }
      const other = s.pegs[i][s.pegs[i].length - 1];
      if (other > k) { found = k; break; }
    }
    i = 3 - i - pos[k - 1];
  }
  return found === -1 ? null : [pos[found - 1], i];
}
for (let n = 1; n <= 6; n++) {
  const s = H.start(n);
  let steps = 0;
  while (!H.won(s) && steps <= 2 ** n) {
    const m = appletHelp(s);
    if (!m) break;
    s.pegs[m[1]].push(s.pegs[m[0]].pop());
    s.seen.add(H.key(s));
    s.moves++;
    steps++;
  }
  check(`${n} disks: the applet's Help() plays the shortest solution, not this one`, H.won(s) && steps === 2 ** n - 1);
  // Approve(): "Congratulations!" plus "Try using fewer moves." once the count
  // reaches 2^N, which a perfect long solve passes almost at once.
  const perfect = H.start(n);
  H.solution(n).forEach(([a, b]) => H.move(perfect, a, b));
  check(`${n} disks: Approve() would scold a perfect long solve`, perfect.moves >= 2 ** n || n === 1);
}

equal("default is 4 disks", H.DEFAULT_DISKS, 4);
equal("1 to 10 disks", [H.MIN_DISKS, H.MAX_DISKS], [1, 10]);

done("long-hanoi");
